import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public final class Inspect {
 static int checks;static void ok(boolean b,String n){checks++;if(!b)throw new AssertionError(n);}static ClassNode cls(ZipFile z,String name)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(name+".class")).readAllBytes()).accept(c,0);return c;}
 public static void main(String[]args)throws Exception{try(ZipFile z=new ZipFile(args[0]);ZipFile quiet=new ZipFile(args[1])){String b="dev/zomboid/hordes/";for(String[]row:new String[][]{{"ChunkPopulation","populate","Population47","populate"},{"HordeEvents","recordGunShot","Heat47","gun"},{"HordeEvents","serverTick","Heat47","server"},{"ZoneSettings","applied","AmbientSettings47","applied"},{"client/AdminScreen","receive","HeatClient47","receive"},{"client/AdminScreen","mouseClicked","SimplePanel","click"},{"client/AdminScreen","mouseDragged","SimplePanel","drag"},{"client/AdminScreen","mouseReleased","SimplePanel","release"},{"client/AdminScreen","mouseScrolled","SimplePanel","wheel"}}){ClassNode c=cls(z,b+row[0]);boolean found=false;for(MethodNode m:c.methods)if(m.name.equals(row[1]))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.owner.equals(b+row[2])&&n.name.equals(row[3]))found=true;ok(found,"native hook: "+Arrays.toString(row));}
 ClassNode screen=cls(z,b+"client/AdminScreen");for(MethodNode m:screen.methods)for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.owner.equals("net/minecraft/network/chat/Component"))ok(n.itf,"Minecraft Component is an interface: "+m.name);
 ClassNode q=cls(quiet,"dev/zomboid/scavenging/Loot");boolean bonus=false;for(MethodNode m:q.methods)if(m.name.equals("bonus")){for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.owner.endsWith("AmbientBridge47")&&n.name.equals("bonus"))bonus=true;}ok(bonus,"native Quietly authority guard");
 ClassNode clientEvent=cls(z,b+"HeatScreenEvents47");ok(clientEvent.visibleAnnotations.get(0).values.toString().contains("value"),"inventory event is client-only");ClassNode join=cls(z,b+"PopulationEvents47");AnnotationNode sub=join.methods.get(0).visibleAnnotations.get(0);ok(((String[])sub.values.get(sub.values.indexOf("priority")+1))[1].equals("HIGHEST"),"population guard runs before entity admission");
 }System.out.println("NATIVE_ENVIRONMENT_HOOKS_ABI_CHECKS="+checks);}
}
